  "content": {
    "user_title": "Dispatch Parallel Agents",
    "value_statement": "When facing multiple independent failures, sequential investigation wastes time. This skill provides a proven pattern to dispatch multiple Claude agents concurrently, reducing investigation time by up to 3x while avoiding resource conflicts.",
    "seo_keywords": [
      "Claude",
      "Codex",
      "Claude Code",
      "parallel agents",
      "multi-agent dispatch",
      "concurrent debugging",
      "agent coordination",
      "parallel processing"
    ],
    "actual_capabilities": [
      "Identify independent problem domains that can be solved in isolation",
      "Create focused agent prompts with clear scope boundaries",
      "Dispatch 3+ agents concurrently using Task tool parallel execution",
      "Merge results from parallel agents without conflicts"
    ],
    "limitations": [
      "Only works when problems are truly independent with no shared state",
      "Cannot handle scenarios requiring whole-system context",
      "Agents must not interfere with shared resources",
      "Relies on proper problem decomposition by the user"
    ],
    "use_cases": [
      {
        "title": "Debug Multiple Independent Failures",
        "description": "When your test suite reports 3+ failures in different modules (auth, API, database), dispatch separate agents to investigate each in parallel. Each agent focuses on one module without stepping on others.",
        "target_user": "Software engineers debugging complex test failures"
      },
      {
        "title": "Parallelize Code Review Tasks",
        "description": "Review multiple pull requests or feature branches simultaneously by sending agents to analyze different code areas. Each agent returns findings that are then consolidated.",
        "target_user": "Tech leads and code reviewers managing large codebases"
      },
      {
        "title": "Simultaneous Documentation Updates",
        "description": "Update documentation across multiple sections or services at once. Each agent handles a specific documentation area, ensuring consistent formatting while avoiding conflicts.",
        "target_user": "Technical writers maintaining multi-module documentation"
      }
    ],
    "prompt_templates": [
      {
        "title": "Basic Parallel Dispatch",
        "prompt": "We have multiple independent failures to investigate:\n\n## Problem 1\nScope: [file/area 1]\nGoal: Find the root cause of [specific issue]\n\n## Problem 2\nScope: [file/area 2]\nGoal: Find the root cause of [specific issue]\n\n## Problem 3\nScope: [file/area 3]\nGoal: Find the root cause of [specific issue]\n\nDispatch these as 3 parallel agents. Each agent should only modify files in their assigned scope.",
        "scenario": "Starting parallel investigation of 3+ independent issues"
      },
      {
        "title": "Parallel Fix Execution",
        "prompt": "The root causes have been identified. Now dispatch agents to implement fixes:\n\n## Fix Agent 1\nTarget: [file 1]\nChange: [specific fix description]\n\n## Fix Agent 2\nTarget: [file 2]\nChange: [specific fix description]\n\nRun these in parallel. Verify tests pass after each fix.",
        "scenario": "Implementing fixes identified during parallel investigation"
      },
      {
        "title": "Concurrent Feature Development",
        "prompt": "Build these independent features concurrently:\n\n## Feature 1\nPath: [module 1]\nDeliverable: [feature specification]\n\n## Feature 2\nPath: [module 2]\nDeliverable: [feature specification]\n\n## Feature 3\nPath: [module 3]\nDeliverable: [feature specification]\n\nDispatch agents to work on each feature. Return code changes for review.",
        "scenario": "Developing multiple independent features in parallel"
      },
      {
        "title": "Parallel Testing Campaign",
        "prompt": "Run tests across these independent test suites concurrently:\n\n## Suite 1\nScope: [test directory 1]\nFocus: [test category]\n\n## Suite 2\nScope: [test directory 2]\nFocus: [test category]\n\n## Suite 3\nScope: [test directory 3]\nFocus: [test category]\n\nExecute in parallel. Collect and compare results.",
        "scenario": "Running multiple test suites simultaneously"
      }
    ],
    "output_examples": [
      {
        "input": "We have 4 test failures in different files: auth.test.js, api.test.js, db.test.js, and cache.test.js. All are independent.",
        "output": [
          "Agent 1: Investigating auth.test.js - Found JWT token expiration issue at auth/jwt.js:45",
          "Agent 2: Investigating api.test.js - Found middleware ordering issue at api/routes.js:12",
          "Agent 3: Investigating db.test.js - Found connection pool exhaustion at db/config.js:8",
          "Agent 4: Investigating cache.test.js - Found TTL configuration at cache/redis.js:23",
          "All 4 issues identified and fixed in parallel. Tests passing."
        ]
      },
      {
        "input": "Update documentation for these 3 independent modules in parallel.",
        "output": [
          "Agent 1: Updated API documentation at docs/api/ - Added new endpoint examples",
          "Agent 2: Updated authentication docs at docs/auth/ - Added OAuth flow diagrams",
          "Agent 3: Updated deployment docs at docs/deploy/ - Added container configuration",
          "Documentation updated across all 3 modules with consistent formatting"
        ]
      }
    ],
    "best_practices": [
      "Clearly define scope boundaries for each agent to prevent overlap",
      "Use the Task tool parallel execution pattern (Task A || Task B || Task C)",
      "Include explicit constraints like 'do not modify files outside scope'"
    ],
    "anti_patterns": [
      "Dispatching agents when problems share state or dependencies",
      "Leaving scope definitions too broad, causing agent conflicts",
      "Not providing clear constraints, leading to duplicate work"
    ],
    "faq": [
      {
        "question": "What makes problems independent?",
        "answer": "Problems are independent when fixing one does not affect the others, they operate on different files or modules, and they do not require shared context to diagnose."
      },
      {
        "question": "How many agents can I dispatch at once?",
        "answer": "The Task tool supports parallel dispatch. Three to five concurrent agents typically work well, depending on your Claude Code configuration."
      },
      {
        "question": "What happens if agents conflict on the same file?",
        "answer": "Clear scope definitions prevent conflicts. If scopes overlap, coordinate sequentially or split the work differently."
      },
      {
        "question": "Can I mix parallel and sequential execution?",
        "answer": "Yes. Run groups of independent problems in parallel, then sequence dependent groups. This handles partial dependencies."
      },
      {
        "question": "How do I verify results from parallel agents?",
        "answer": "Each agent should return structured findings. Compare results, run tests, and merge changes using standard version control."
      },
      {
        "question": "When should I avoid this pattern?",
        "answer": "Avoid when problems require shared context, when fixes might affect each other, or when system-wide changes are needed."
      }
    ]
